(root/'tests/test_kingdom_android.py').write_text('''from pathlib import Path\nimport unittest\nr=Path(__file__).resolve().parents[1];a=r/'android/app/src/main/assets'\nclass TestKingdom(unittest.TestCase):\n def test_tabs_and_studio(self):\n  h=(a/'kingdom.html').read_text()\n  for x in ('home','needs','services','commons','fellowship'):self.assertIn('data-tab="'+x+'"',h)\n  self.assertIn('Open Sermon Studio',h);self.assertIn('simulations',h)\n def test_navigation(self):\n  self.assertIn('href="kingdom.html"',(a/'index.html').read_text())\n  self.assertIn('ASSET_HOME="file:///android_asset/kingdom.html"',(r/'android/app/src/main/java/org/kingdom/pocketscribe/MainActivity.java').read_text())\n  self.assertIn("applicationId 'org.kingdom.ofheaven'",(r/'android/app/build.gradle').read_text())\n def test_native_tools(self):\n  h=(a/'index.html').read_text()\n  for x in ('download-qwen','download-kokoro','ask-form','sigilCanvas'):self.assertIn(x,h)\n''')
